  /// 1. Seed bảng tra cứu Cơ sở và BHYT
  static Future<void> seedLookupTables() async {
    print('⏳ Đang tạo các bảng tra cứu (CoSo, BHYT)...');

    await _firestore.collection('CoSo').doc('Cong_lap').set({
      'ten_co_so': 'Công lập',
    }, SetOptions(merge: true));
    await _firestore.collection('CoSo').doc('Tu_nhan').set({
      'ten_co_so': 'Tư nhân',
    }, SetOptions(merge: true));

    await _firestore.collection('BHYT').doc('Co_BHYT').set({
      'ten_bhyt': 'Có BHYT',
    }, SetOptions(merge: true));
    await _firestore.collection('BHYT').doc('Khong_BHYT').set({
      'ten_bhyt': 'Không BHYT',
    }, SetOptions(merge: true));

    print('✅ Hoàn tất bảng tra cứu!\n');
  }

  /// 2. Seed bệnh viện từ file GeoJSON
  static Future<void> seedHospitalsFromJson() async {
    print('⏳ Đang đọc và xử lý dữ liệu bệnh viện từ file JSON...');

    try {
      final jsonString = await rootBundle.loadString('hospital.geojson');
      final jsonData = jsonDecode(jsonString);

      if (jsonData is! Map || jsonData['features'] is! List) {
        throw Exception(
          'Cấu trúc file JSON không hợp lệ hoặc thiếu key "features"',
        );
      }

      final features = jsonData['features'] as List;
      final random = Random();

      int congLapCount = 0;
      int coBhytCount = 0;
      int successCount = 0;

      print('🔄 Bắt đầu xử lý ${features.length} cơ sở y tế...');

      for (int i = 0; i < features.length; i++) {
        final feature = features[i];
        final props = feature['properties'] as Map<String, dynamic>? ?? {};
        final geom = feature['geometry'] as Map<String, dynamic>?;

        final coords = geom?['coordinates'] as List<dynamic>?;
        if (coords == null || coords.length < 2) continue;

        final lon = (coords[0] as num).toDouble(); // Kinh độ
        final lat = (coords[1] as num).toDouble(); // Vĩ độ

        // --- XỬ LÝ DỮ LIỆU THEO QUY TẮC ---
        String name = props['name'] ?? 'Cơ sở y tế ${i + 1}';
        String cleanName = name.toLowerCase().replaceAll(
          RegExp(r'[^a-z0-9]'),
          '',
        );
        if (cleanName.isEmpty) cleanName = 'benhvien';

        String address = props['addr:full'] ?? '';
        if (address.isEmpty) {
          String number = props['addr:housenumber'] != null
              ? '${props['addr:housenumber']}, '
              : '';
          String street = props['addr:street'] ?? 'Đường chưa rõ tên';
          String ward = props['addr:subdistrict'] != null
              ? '${props['addr:subdistrict']}, '
              : '';
          String district = props['addr:district'] != null
              ? '${props['addr:district']}, '
              : '';
          String city =
              props['addr:city'] ?? props['addr:province'] ?? 'Việt Nam';
          address = '${number}${street}, ${ward}${district}${city}'
              .replaceAll(RegExp(r', ,'), ', ')
              .replaceAll(RegExp(r'  '), ' ')
              .trim();
        }

        String email = props['email'] ?? props['contact:email'] ?? '';
        if (email.isEmpty) {
          email = '${cleanName}${i + 1}@gmail.com';
        }

        String coSo = (congLapCount < 350) ? 'Cong_lap' : 'Tu_nhan';
        if (coSo == 'Cong_lap') congLapCount++;

        String bhyt = (coBhytCount < 400) ? 'Co_BHYT' : 'Khong_BHYT';
        if (bhyt == 'Co_BHYT') coBhytCount++;

        double rating = 3.0 + (random.nextDouble() * 2.0);
        int reviews = 100 + random.nextInt(201);

        final maBenhVien = 'BV${(i + 1).toString().padLeft(3, '0')}';
        final trangThaiId = '10';

        // =====================================================================
        // ✅ SỬA ĐÚNG: TẠO NGẪU NHIÊN 3-6 CHUYÊN KHOA CHO BỆNH VIỆN NÀY
        // =====================================================================
        final numSpecialties = random.nextInt(4) + 3; // Random từ 3 đến 6

        // Xáo trộn danh sách 30 chuyên khoa và lấy ra số lượng đã chọn
        final shuffledPool = List<Map<String, String>>.from(_specialtiesPool)
          ..shuffle(random);
        final selectedDepartments = shuffledPool.take(numSpecialties).toList();

        // Trích xuất ID (CK01, CK02...) và Tên khoa
        final deptList = <Map<String, String>>[];
        for (final dept in selectedDepartments) {
          final originalIndex = _specialtiesPool.indexOf(dept);
          final ckId = 'CK${(originalIndex + 1).toString().padLeft(2, '0')}';
          deptList.add({
            'ten_khoa': dept['ten_khoa']!,
            'mo_ta': dept['mo_ta']!,
            'chuyen_khoa_id': ckId,
          });
        }

        final specialtyIds = deptList.map((d) => d['chuyen_khoa_id']!).toList();
        final specialtyNames = deptList.map((d) => d['ten_khoa']!).toList();

        // Lưu lại để seedDepartments dùng đúng danh sách này
        _departmentsByHospital[maBenhVien] = deptList;
        // =====================================================================

        // --- XÂY DỰNG ĐƯỜNG DẪN SÂU (Deep Nesting) ---
        final docRef = _firestore
            .collection('BenhVien')
            .doc(trangThaiId)
            .collection('co_so')
            .doc(coSo)
            .collection('bhyt')
            .doc(bhyt)
            .collection('danh_sach')
            .doc(maBenhVien);

        final docSnapshot = await docRef.get();

        // Dữ liệu khớp 100% với HospitalModel
        final hospitalData = {
          'ten_benh_vien': name,
          'dia_chi': address,
          'hinh_anh': '',
          'trang_thai_hop_tac_id': 10,
          'diem_danh_gia_tb': double.parse(rating.toStringAsFixed(1)),
          'tong_so_danh_gia': reviews,
          'co_so': coSo == 'Cong_lap' ? 'Công lập' : 'Tư nhân',
          'bhyt': bhyt == 'Co_BHYT' ? 'Có BHYT' : 'Không BHYT',
          'email': email,
          'role': 'benh_vien',
          'da_xac_thuc_email': true,
          'vi_do': lat,
          'kinh_do': lon,

          // ✅ GÁN ĐÚNG: Sử dụng 2 biến list vừa tạo ở trên
          'chuyen_khoa_ids': specialtyIds,
          'ten_cac_khoa': specialtyNames,

          if (!docSnapshot.exists) 'ngay_tao': FieldValue.serverTimestamp(),
          'ngay_cap_nhat': FieldValue.serverTimestamp(),
        };

        await docRef.set(hospitalData, SetOptions(merge: true));
        successCount++;

        if (successCount % 50 == 0) {
          print('   ✅ Đã xử lý $successCount bệnh viện...');
        }
      }

      print('\n✅ Hoàn tất seeding!');
      print('📊 Tổng cộng: $successCount bệnh viện.');
      print(
        '📊 Thống kê: $congLapCount Công lập, ${successCount - congLapCount} Tư nhân.',
      );
      print(
        '📊 Thống kê: $coBhytCount Có BHYT, ${successCount - coBhytCount} Không BHYT.',
      );
    } catch (e) {
      print('❌ Lỗi khi seeding từ JSON: $e');
      print('💡 Đảm bảo đã khai báo "hospital.geojson" trong pubspec.yaml');
      rethrow;
    }
  }

  /// 3. Seed khoa (Cấu trúc Collection riêng biệt)
  static Future<void> seedDepartments() async {
    if (_departmentsByHospital.isEmpty) {
      print(
        '⚠️ Chưa có dữ liệu bệnh viện. Hãy chạy seedHospitalsFromJson() trước.',
      );
      return;
    }

    print(
      '⏳ Đang tạo dữ liệu khoa theo đúng chuyên khoa của từng bệnh viện...',
    );
    int totalDepartments = 0;
    int failedCount = 0;

    for (final entry in _departmentsByHospital.entries) {
      final hospitalId = entry.key;
      final depts = entry.value;

      try {
        final col = _firestore
            .collection('Khoa')
            .doc(hospitalId)
            .collection('danh_sach');

        // Xoá khoa cũ để không còn document thừa từ lần seed trước
        final old = await col.get();
        final batch = _firestore.batch();
        for (final doc in old.docs) {
          batch.delete(doc.reference);
        }

        for (var i = 0; i < depts.length; i++) {
          final deptId = 'K${(i + 1).toString().padLeft(3, '0')}';
          batch.set(col.doc(deptId), {
            'id': deptId,
            'ten_khoa': depts[i]['ten_khoa'],
            'mo_ta': depts[i]['mo_ta'],
            'chuyen_khoa_id': depts[i]['chuyen_khoa_id'],
            'ngay_tao': FieldValue.serverTimestamp(),
            'ngay_cap_nhat': FieldValue.serverTimestamp(),
          });
          totalDepartments++;
        }

        await batch.commit();
      } catch (e) {
        failedCount++;
        print('❌ Lỗi khi tạo khoa cho bệnh viện $hospitalId: $e');
      }
    }

    if (failedCount > 0)
      print('⚠️ Có $failedCount bệnh viện gặp lỗi khi tạo khoa.');
    print(
      '✅ Hoàn tất seeding $totalDepartments khoa cho ${_departmentsByHospital.length} bệnh viện!\n',
    );
  }

  /// Hàm chạy tất cả các tác vụ seeding
  static Future<void> seedAllData() async {
    print('⏳ Bắt đầu quá trình seeding toàn bộ dữ liệu...');
    try {
      await seedLookupTables();
      await seedHospitalsFromJson(); // ✅ Dùng hàm mới đọc từ JSON
      await seedDepartments();
      print('\n🎉 HOÀN TẤT SEEDING TOÀN BỘ DỮ LIỆU!');
    } catch (error) {
      print('❌ Seeder thất bại: $error');
    }
  }
}
